<script setup>
import AdminNavigation from '@/Components/Admin/AdminNavigation.vue'; import PortalLayout from '@/Layouts/PortalLayout.vue'; import { Head,Link,router } from '@inertiajs/vue3'; import { computed,reactive } from 'vue'; const props=defineProps({leads:{type:Array,required:true},filters:{type:Object,required:true},statuses:{type:Array,required:true},products:{type:Array,required:true},salesOfficers:{type:Array,required:true}}); const filters=reactive({view:props.filters.view||'table',search:props.filters.search||'',status:props.filters.status||'',product_id:props.filters.product_id||'',assigned_to:props.filters.assigned_to||'',follow_up:props.filters.follow_up||''}); const apply=()=>router.get(route('admin.leads.index'),filters,{preserveState:true,replace:true}); const switchView=(view)=>{filters.view=view;apply();}; const grouped=computed(()=>Object.fromEntries(props.statuses.map(status=>[status,props.leads.filter(lead=>lead.status===status)])));
</script>
<template><Head title="CRM Pipeline"/><PortalLayout area="Administration"><template #navigation><AdminNavigation active="leads"/></template><div class="mb-6 flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between"><div><p class="text-sm font-bold uppercase text-cyan-700">Sales</p><h1 class="mt-1 text-3xl font-bold">CRM pipeline</h1><p class="mt-2 text-slate-600">Manage demo opportunities from first contact to conversion.</p></div><div class="flex rounded-xl border border-slate-300 bg-white p-1"><button class="rounded-lg px-4 py-2 text-sm font-bold" :class="filters.view==='table'?'bg-[#0B3D6E] text-white':'text-slate-600'" @click="switchView('table')">Table</button><button class="rounded-lg px-4 py-2 text-sm font-bold" :class="filters.view==='pipeline'?'bg-[#0B3D6E] text-white':'text-slate-600'" @click="switchView('pipeline')">Pipeline</button></div></div><form class="mb-6 grid gap-3 rounded-2xl bg-white p-4 shadow-sm md:grid-cols-3 xl:grid-cols-6" @submit.prevent="apply"><input v-model="filters.search" placeholder="Search lead or organization"/><select v-model="filters.status"><option value="">All statuses</option><option v-for="status in statuses" :key="status" :value="status">{{ status.replaceAll('_',' ') }}</option></select><select v-model="filters.product_id"><option value="">All products</option><option v-for="product in products" :key="product.id" :value="product.id">{{ product.name }}</option></select><select v-model="filters.assigned_to"><option value="">All sales officers</option><option v-for="user in salesOfficers" :key="user.id" :value="user.id">{{ user.name }}</option></select><select v-model="filters.follow_up"><option value="">Any follow-up</option><option value="overdue">Overdue</option><option value="today">Today</option><option value="upcoming">Upcoming</option><option value="none">Not set</option></select><button class="form-button !py-2">Apply filters</button></form>
<div v-if="filters.view==='table'" class="overflow-x-auto rounded-2xl border border-slate-200 bg-white shadow-sm"><table class="w-full min-w-[900px] text-left"><thead class="bg-slate-50 text-xs uppercase text-slate-500"><tr><th class="p-4">Lead</th><th class="p-4">Status</th><th class="p-4">Product</th><th class="p-4">Assigned</th><th class="p-4">Follow-up</th><th class="p-4"></th></tr></thead><tbody><tr v-for="lead in leads" :key="lead.id" class="border-t border-slate-100"><td class="p-4"><Link :href="route('admin.leads.show',lead.id)" class="font-bold text-[#0B3D6E]">{{ lead.organization||lead.name }}</Link><p class="text-sm text-slate-500">{{ lead.lead_number }} · {{ lead.email }}</p></td><td class="p-4"><span class="rounded-full bg-slate-100 px-2 py-1 text-xs font-bold uppercase">{{ lead.status.replaceAll('_',' ') }}</span></td><td class="p-4 text-sm">{{ lead.product?.name||'Unspecified' }}</td><td class="p-4 text-sm">{{ lead.assigned_user?.name||'Unassigned' }}</td><td class="p-4 text-sm" :class="lead.follow_up_date&&new Date(lead.follow_up_date)<new Date()?'font-bold text-red-600':''">{{ lead.follow_up_date||'—' }}</td><td class="p-4"><Link :href="route('admin.leads.show',lead.id)" class="text-sm font-bold text-cyan-700">Open →</Link></td></tr></tbody></table><p v-if="!leads.length" class="p-10 text-center text-slate-500">No leads match these filters.</p></div>
<div v-else class="flex gap-4 overflow-x-auto pb-5"><section v-for="status in statuses" :key="status" class="w-72 shrink-0 rounded-2xl bg-slate-200/70 p-3"><header class="flex items-center justify-between px-2 py-2"><h2 class="text-sm font-bold capitalize text-slate-700">{{ status.replaceAll('_',' ') }}</h2><span class="rounded-full bg-white px-2 py-0.5 text-xs font-bold">{{ grouped[status].length }}</span></header><div class="mt-2 space-y-3"><Link v-for="lead in grouped[status]" :key="lead.id" :href="route('admin.leads.show',lead.id)" class="block rounded-xl bg-white p-4 shadow-sm hover:shadow-md"><h3 class="font-bold text-[#0B3D6E]">{{ lead.organization||lead.name }}</h3><p class="mt-1 text-xs text-slate-500">{{ lead.product?.name||'Product not selected' }}</p><div class="mt-3 flex justify-between text-xs text-slate-500"><span>{{ lead.assigned_user?.name||'Unassigned' }}</span><span>{{ lead.follow_up_date||'' }}</span></div></Link><p v-if="!grouped[status].length" class="p-4 text-center text-xs text-slate-500">No leads</p></div></section></div></PortalLayout></template>
